// Sakura — WebGL "Mesh drift" background from 21st.dev (@altered-data/sakura),
// generated by the 21st.dev Shader Builder. Trimmed to the uniforms this preset uses.
import { useEffect, useRef } from 'react'

const VERT = `attribute vec2 a_position;
void main() { gl_Position = vec4(a_position, 0.0, 1.0); }`

const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform vec3 u_colors[8];
uniform vec4 u_scene;     // resolution.xy, time, colour count
uniform vec4 u_shape;     // scale, intensity, paramA, warp
uniform vec4 u_surface;   // detail, contrast, brightness, saturation
uniform vec4 u_finish;    // hue, vignette, blur, grain
uniform vec4 u_transform; // seed, rotation, drift, oklab
#define u_resolution u_scene.xy
#define u_time u_scene.z
#define u_colorCount u_scene.w
#define u_scale u_shape.x
#define u_intensity u_shape.y
#define u_contrast u_surface.y
#define u_brightness u_surface.z
#define u_saturation u_surface.w
#define u_vignette u_finish.y
#define u_grain u_finish.w
#define u_seed u_transform.x
#define u_drift u_transform.z

float grainHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec3 shade(vec2 p, float t) {
  vec3 acc = u_colors[0] * 0.15;
  float total = 0.15;
  for (int i = 0; i < 8; i++) {
    if (float(i) >= u_colorCount) break;
    float fi = float(i);
    vec2 c = vec2(
      sin(t * (0.21 + fi * 0.071) + fi * 2.4 + u_seed),
      cos(t * (0.17 + fi * 0.093) + fi * 1.7)) * (0.45 + u_intensity * 0.35);
    float w = exp(-dot(p - c, p - c) * 6.0);
    acc += u_colors[i] * w;
    total += w;
  }
  return acc / total;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / min(u_resolution.x, u_resolution.y);
  p *= u_scale;
  p += u_drift * vec2(sin(u_time * 0.31), cos(u_time * 0.23));
  vec3 col = shade(p, u_time);
  col = (col - 0.5) * u_contrast + 0.5;
  float luma = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(luma), col, u_saturation);
  col += u_brightness;
  float vd = length(uv - 0.5) * 1.41421356;
  col *= 1.0 - u_vignette * smoothstep(0.35, 1.0, vd);
  col += (grainHash(gl_FragCoord.xy + vec2(u_seed * 17.0, u_seed * 31.0)) - 0.5) * u_grain;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}`

const hex = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255)
const PALETTE = ['#1A1423', '#B75D69', '#EACDC2', '#FFF5EB']
const U = {
  scale: 1.16,
  intensity: 0.34,
  contrast: 1.158,
  brightness: -0.18,
  saturation: 0.54,
  vignette: 0.55,
  grain: 0.059,
  seed: 1453.0,
  drift: 0.4,
  timeScale: 0.214,
}

export function SakuraShader({ className }: { className?: string }) {
  const ref = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const gl = canvas.getContext('webgl', { antialias: false })
    if (!gl) return
    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!
      gl.shaderSource(s, src)
      gl.compileShader(s)
      return s
    }
    const prog = gl.createProgram()!
    gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT))
    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG))
    gl.linkProgram(prog)
    gl.useProgram(prog)
    const buf = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buf)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
    const loc = gl.getAttribLocation(prog, 'a_position')
    gl.enableVertexAttribArray(loc)
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0)

    const colors = [...PALETTE, ...Array(8 - PALETTE.length).fill(PALETTE.at(-1))].flatMap(hex)
    gl.uniform3fv(gl.getUniformLocation(prog, 'u_colors'), new Float32Array(colors))
    gl.uniform4f(gl.getUniformLocation(prog, 'u_shape'), U.scale, U.intensity, 0.5, 0)
    gl.uniform4f(gl.getUniformLocation(prog, 'u_surface'), 2.4, U.contrast, U.brightness, U.saturation)
    gl.uniform4f(gl.getUniformLocation(prog, 'u_finish'), 0, U.vignette, 0, U.grain)
    gl.uniform4f(gl.getUniformLocation(prog, 'u_transform'), U.seed, 0, U.drift, 0)
    const scene = gl.getUniformLocation(prog, 'u_scene')

    let raf = 0
    const t0 = performance.now()
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches
    const size = () => {
      const r = canvas.getBoundingClientRect()
      // Half resolution: a soft gradient doesn't need full pixels, and it saves battery.
      const w = Math.max(1, Math.round(r.width * 0.5))
      const h = Math.max(1, Math.round(r.height * 0.5))
      if (canvas.width !== w || canvas.height !== h) {
        canvas.width = w
        canvas.height = h
        gl.viewport(0, 0, w, h)
      }
    }
    const frame = (now: number) => {
      raf = 0
      size()
      gl.uniform4f(scene, canvas.width, canvas.height, ((now - t0) / 1000) * U.timeScale, PALETTE.length)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
      if (!reduce && document.visibilityState === 'visible') raf = requestAnimationFrame(frame)
    }
    const onVis = () => document.visibilityState === 'visible' && !raf && (raf = requestAnimationFrame(frame))
    raf = requestAnimationFrame(frame)
    document.addEventListener('visibilitychange', onVis)
    window.addEventListener('resize', onVis)
    return () => {
      cancelAnimationFrame(raf)
      document.removeEventListener('visibilitychange', onVis)
      window.removeEventListener('resize', onVis)
      gl.deleteBuffer(buf)
      gl.deleteProgram(prog)
      gl.getExtension('WEBGL_lose_context')?.loseContext()
    }
  }, [])
  return <canvas ref={ref} className={className} style={{ display: 'block', width: '100%', height: '100%' }} />
}
